function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Start by painting the sky
  brush.fill("#7a5e4b", 0.5); // Light blue sky
  brush.circle(200, 200, 150);

  // Next, draw the green hills
  brush.fill("#0e683b", 0.3); // Dark green hills
  brush.vertex(200, 100); // Top of the hill
  brush.vertex(100, 100); // Left of the hill
  brush.vertex(0, 100); // Bottom of the hill
  brush.vertex(100, 200); // Right of the hill
  brush.endShape(true);

  // Add some details to the hills
  brush.fill("#0e683b", 0.3); // Medium green hills
  brush.vertex(0, 250); // Top of the hill
  brush.vertex(0, 200); // Left of the hill
  brush.vertex(0, 150); // Bottom of the hill
  brush.vertex(100, 250); // Right of the hill
  brush.endShape(true);

  // Add a purple sun
  brush.fill("#db1c2e", 0.5); // Violet sun
  brush.vertex(0, 250); // Top of the sun
  brush.vertex(0, 225); // Left of the sun
  brush.vertex(0, 200); // Bottom of the sun
  brush.vertex(100, 250); // Right of the sun
  brush.endShape(true);
}

