function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Handle the sky
  brush.fill("#87CEFA", 0); // Sky color, with 0 opacity (transparent)
  brush.circle(0, 0, 400);

  // Handle the green hills
  brush.fill("#29561A", 100); // Green color, with 100% opacity
  brush.fillBleed(0.2); // 20% bleed effect
  brush.circle(0, 0, 300); // Draw a hill

  // Create multiple hills for a green landscape
  brush.fill("#29561A", 50); // Half opacity for the hills
  brush.fillBleed(0.3); // 30% bleed effect
  brush.circle(-150, 0, 300); // Draw another hill to the left
  brush.fill("#29561A", 75); // Full opacity for the hills
  brush.fillBleed(0.4); // 40% bleed effect
  brush.circle(-200, 0, 250); // Draw a third hill to the left

  // Create more hills for a green landscape
  brush.fill("#29561A", 100); // Full opacity for the hills
  brush.fillBleed(0.5); // 50% bleed effect
  brush.circle(-250, 0, 200); // Draw a fourth hill to the left
  brush.fill("#29561A", 75); // Half opacity for the hills
  brush.fillBleed(0.6); // 60% bleed effect
  brush.circle(-300, 0, 150); // Draw a fifth hill to the left

